import numpy as np
from scipy.optimize import minimize_scalar


def run_node(inputs: dict) -> dict:
    prefix = inputs['node_00']
    u, v = prefix['u'], prefix['v1']

    def basis(z, p):
        return 0.45*z + np.tanh(p*z)

    def fit(p):
        f = basis(u, p)
        mean = f.mean(axis=0)
        g = f - mean
        left, singular, right = np.linalg.svd(g.T @ (v - v.mean(axis=0)))
        mat = (left @ right) * (singular.sum() / np.sum(g*g))
        bias = v.mean(axis=0) - mean @ mat
        return mat, bias

    def error(p):
        mat, bias = fit(p)
        return np.sum((basis(u, p) @ mat + bias - v)**2)

    p = minimize_scalar(error, bounds=(0.5, 4), method='bounded').x
    mat, bias = fit(p)
    return {'a': basis(prefix['z'], p) @ mat + bias}

